def require(ok, message):
    if not ok:
        raise RuntimeError(message)


def digest(data):
    return hashlib.sha256(data).hexdigest()


def load_payload():
    raw = zlib.decompress(base64.b85decode(PAYLOAD_B85))
    require(digest(raw) == PAYLOAD_SHA, "TRANSFER_PAYLOAD_HASH_MISMATCH")
    data = json.loads(raw)
    require(data['base'] == BASE and data['branch'] == 'meta-ads-api', 'TRANSFER_BASE_MISMATCH')
    for name, entry in data['files'].items():
        path = PurePosixPath(name)
        require(not path.is_absolute() and '..' not in path.parts and
                path.parts[0] in ('scripts', 'src') and str(path) == name, 'UNSAFE_TRANSFER_PATH')
        require(digest(base64.b64decode(entry['data'], validate=True)) == entry['sha256'], 'TRANSFER_FILE_HASH_MISMATCH:' + name)
    return data


def apply_payload(repo, payload):
    # Complete preflight before writing any source file.
    for name, entry in payload['files'].items():
        target = repo / name
        require(not target.is_symlink() and target.resolve().is_relative_to(repo.resolve()), 'UNSAFE_CHECKOUT_PATH')
        if entry['base_sha256'] is None:
            require(not target.exists(), 'NEW_FILE_ALREADY_EXISTS:' + name)
        else:
            require(target.is_file() and digest(target.read_bytes()) == entry['base_sha256'], 'BASE_FILE_DRIFT:' + name)
    for name, entry in payload['files'].items():
        target = repo / name
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(base64.b64decode(entry['data']))
        require(digest(target.read_bytes()) == entry['sha256'], 'WRITTEN_FILE_HASH_MISMATCH:' + name)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--run', action='store_true', help='Create a fresh workspace, install isolated tools and run local fixture DB tests')
    parser.add_argument('--inspect-payload', action='store_true', help='Verify embedded files only; no writes/network/DB')
    parser.add_argument('--runtime-root', type=Path, default=Path.home()/'Downloads/etrylue-meta-pg17-6')
    args = parser.parse_args()
    payload = load_payload()
    if args.inspect_payload:
        print(json.dumps({'transfer': 'PASS', 'files': len(payload['files']), 'base': BASE, 'db_executions': 0}))
        return
    require(args.run, 'Specify --run to execute, or --inspect-payload for read-only verification')
    require(sys.version_info >= (3, 9), 'PYTHON_3_9_OR_NEWER_REQUIRED')
    require(sys.platform == 'darwin' and os.geteuid() != 0, 'MAC_NON_ROOT_USER_REQUIRED')
    runtime = args.runtime_root.expanduser().resolve(strict=True)
    require(not runtime.is_relative_to(PROTECTED), 'PROTECTED_PATH_FORBIDDEN')
    readiness = json.loads((runtime/'runtime-readiness.json').read_text())
    pg_bin = runtime/'install/bin'
    require(readiness['status'] == 'PASS_BINARY_PREPARATION_ONLY' and readiness['uid'] == os.geteuid()
            and readiness['pg_bin'] == str(pg_bin) and readiness['pgcrypto_control_version'] == '1.3', 'RUNTIME_READINESS_MISMATCH')
    for name in ('postgres', 'initdb', 'pg_ctl', 'psql'):
        require(digest((pg_bin/name).read_bytes()) == readiness['versions'][name]['sha256'], 'RUNTIME_BINARY_DRIFT:' + name)
    git = shutil.which('git')
    conda = shutil.which('conda')
    require(git and conda, 'GIT_AND_CONDA_REQUIRED')
    downloads = (Path.home()/'Downloads').resolve(strict=True)
    require(not downloads.is_relative_to(PROTECTED), 'PROTECTED_PATH_FORBIDDEN')
    os.umask(0o077)
    work = Path(tempfile.mkdtemp(prefix='etrylue-meta-validation-', dir=downloads))
    log_path = work/'run.log'
    print('WORKSPACE=' + str(work), flush=True)
    print('LOG=' + str(log_path), flush=True)
    with log_path.open('w') as log:
        def run(argv, cwd=work, env=None):
            print('STEP: ' + Path(str(argv[0])).name + ' ' + str(argv[1]), flush=True)
            with subprocess.Popen([str(x) for x in argv], cwd=cwd, env=env, stdout=subprocess.PIPE,
                                  stderr=subprocess.STDOUT, text=True, errors='replace') as process:
                for line in process.stdout:
                    print(line, end='', flush=True)
                    log.write(line); log.flush()
                require(process.wait() == 0, 'STEP_FAILED: ' + str(argv[0]) + '; log=' + str(log_path))
        try:
            repo = work/'dashboard-meta-ads-api'
            # Only this fresh clone is checked out. Existing repositories are never opened.
            run([git, '-c', 'core.hooksPath=/dev/null', 'clone', '--no-checkout', '--depth=1', '--single-branch',
                 '--branch', 'meta-ads-api', 'https://github.com/gyurinpapa/dashboard.git', repo])
            head = subprocess.check_output([git, 'rev-parse', 'HEAD'], cwd=repo, text=True).strip()
            require(head == BASE, 'REMOTE_BRANCH_MOVED: expected ' + BASE + ', observed ' + head)
            run([git, '-c', 'core.hooksPath=/dev/null', 'checkout', 'meta-ads-api'], cwd=repo)
            apply_payload(repo, payload)
            (work/'transfer-manifest.json').write_text(json.dumps({
                'base': BASE, 'branch': 'meta-ads-api', 'files': {
                    name: {k:v for k,v in entry.items() if k != 'data'} for name,entry in payload['files'].items()
                }, 'db_execution_at_transfer': 0}, indent=2)+'\n')
            toolchain = work/'toolchain'
            run([conda, 'create', '--yes', '--override-channels', '--channel', 'conda-forge',
                 '--prefix', toolchain, 'python=3.12', 'nodejs=22'])
            env = dict(os.environ)
            env['PATH'] = str(toolchain/'bin') + os.pathsep + os.defpath
            deps = work/'fixture-tools'
            deps.mkdir()
            (deps/'package.json').write_text('{"name":"meta-fixture-tools","private":true}\n')
            run([toolchain/'bin/npm', 'install', '--prefix', deps, '--ignore-scripts', '--no-audit', '--no-fund',
                 '--registry=https://registry.npmjs.org', '--save-exact', 'tsx@4.22.3'], env=env)
            (repo/'node_modules').symlink_to(deps/'node_modules', target_is_directory=True)
            output = work/'results'
            # Harness strips DB connection environment and creates its own private cluster.
            run([toolchain/'bin/python3', '-B', 'scripts/meta_ads_isolated_harness.py', '--prepare', output,
                 '--run-isolated', '--pg-bin', pg_bin, '--performance-rows', '2001'], cwd=repo, env=env)
            require((output/'runtime-result.json').is_file(), 'RUNTIME_RESULT_MISSING')
            print('RESULT=' + str(output/'runtime-result.json'), flush=True)
            print('LOG=' + str(log_path), flush=True)
        except BaseException as error:
            log.write('\nRUNNER_ERROR: ' + str(error) + '\n'); log.flush()
            print('FAILED. Keep workspace and send this log: ' + str(log_path), file=sys.stderr)
            raise


if __name__ == '__main__':
    main()
